top N churn-risk accounts grouped by pla.shapeJs:
function shape(rows) {
  const byPlan = new Map();
  for (const r of rows) {
    if (!byPlan.has(r.plan)) byPlan.set(r.plan, []);
    byPlan.get(r.plan).push({ name: r.name, churnRisk: r.churn_risk, lastInvoiceStatus: r.last_invoice_status });
  }
  return { plans: [...byPlan].map(([plan, accounts]) => ({ plan, accounts })) };
}
